//! Revision-checked local draft and user-confirmed JMAP submission. No automatic retries.
use crate::*;
fn binding(m:&email::Mailbox)->Value{json!({"endpoint":m.endpoint,"account":m.account,"mailbox":m.mailbox,"credential":m.credential})}
fn address(s:&str)->Result<(),String>{if s.len()>254||!s.is_ascii()||s.chars().any(|c|c.is_whitespace()||c.is_control()||"<>,;\"\\".contains(c))||s.matches('@').count()!=1||s.split('@').any(str::is_empty){return Err("Enter one explicit email address per recipient".into())}Ok(())}
fn recipients(d:&Value)->String{d["to"].as_array().into_iter().flatten().filter_map(Value::as_str).collect::<Vec<_>>().join(", ")}
fn review(d:&Value)->String{let names=d["attachments"].as_array().into_iter().flatten().filter_map(|a|a["name"].as_str()).collect::<Vec<_>>().join(", ");format!("From: {}\nTo: {}\nSubject: {}\nAttachments: {}",d["from"].as_str().unwrap_or(""),recipients(d),d["subject"].as_str().unwrap_or(""),if names.is_empty(){"None"}else{&names})}
pub fn validate(d:&Value)->Result<(),String>{address(d["from"].as_str().ok_or("Choose sender")?)?;let to=d["to"].as_array().filter(|a|!a.is_empty()&&a.len()<=10).ok_or("Choose1–10 recipients")?;let mut seen=std::collections::BTreeSet::new();for v in to{let s=v.as_str().ok_or("Invalid recipient")?;address(s)?;if !seen.insert(s.to_ascii_lowercase()){return Err("Duplicate recipient".into())}}email_content::text(&d["subject"],240,false)?;email_content::text(&d["text"],8000,true)?;let a=d["attachments"].as_array().filter(|a|a.len()<=3).ok_or("At most three server-blob attachments")?;for v in a{email_content::attachment(v)?;}if d.to_string().len()>13000{return Err("Draft exceeds13KiB".into())}Ok(())}
#[derive(Clone)]pub struct Options{pub slot:String,pub upload_url:Option<String>,pub sent_mailbox:Option<String>}
impl Default for Options{fn default()->Self{Self{slot:"draft".into(),upload_url:None,sent_mailbox:None}}}
fn store(s:&Value)->Value{collections::transact("mail_draft",s["revision"].as_u64().unwrap_or(0),1,None,vec![collections::put(s["slot"].as_str().unwrap_or("draft"),json!({"binding":s["binding"],"draft":s["draft"],"identity":s["identity"],"phase":s["phase"],"attempt":s["attempt"],"server_email":s["server_email"],"move_needed":s["move_needed"]}))],"compose.saved")}
fn submission(m:&email::Mailbox,identity:&str,d:&Value,message_id:Option<&str>)->Result<Value,String>{validate(d)?;email_content::ident(identity)?;email::request(m,0,"validate")?;let to:Vec<_>=d["to"].as_array().unwrap().iter().map(|v|json!({"email":v})).collect();let mut mailboxes=json!({});mailboxes[&m.mailbox]=json!(true);let attachments:Vec<_>=d["attachments"].as_array().unwrap().iter().map(|a|json!({"blobId":a["blobId"],"type":a["type"],"name":a["name"],"disposition":"attachment"})).collect();let mut data=json!({"using":["urn:ietf:params:jmap:core","urn:ietf:params:jmap:mail","urn:ietf:params:jmap:submission"],"methodCalls":[["Email/set",{"accountId":m.account,"create":{"draft":{"mailboxIds":mailboxes,"keywords":{"$draft":true},"from":[{"email":d["from"]}],"to":to,"subject":d["subject"],"textBody":[{"partId":"text","type":"text/plain"}],"bodyValues":{"text":{"value":d["text"]}},"attachments":attachments}}},"create"],["EmailSubmission/set",{"accountId":m.account,"create":{"send":{"identityId":identity,"emailId":"#draft"}}},"submit"]]});if let Some(id)=message_id{data["methodCalls"][0][1]["create"]["draft"]["header:Message-ID:asMessageIds"]=json!([id]);}Ok(accounts::authenticated(http::post_json(&m.endpoint,&data,"compose.submitted"),&m.credential))}
fn accepted(m:&email::Mailbox,r:&Value)->bool{if r["status"]!=200{return false}let Ok(raw)=http::parse_json(r)else{return false};let Some(rows)=raw["methodResponses"].as_array().filter(|r|r.len()==2)else{return false};for(tag,name,key)in[("create","Email/set","draft"),("submit","EmailSubmission/set","send")]{let matching:Vec<_>=rows.iter().filter(|r|r[2]==tag).collect();if matching.len()!=1{return false}let row=matching[0];if row.as_array().is_none_or(|r|r.len()!=3)||row[0]!=name||row[1]["accountId"]!=m.account||row[1]["notCreated"].get(key).is_some(){return false}let Some(id)=row[1]["created"][key]["id"].as_str()else{return false};if email_content::ident(id).is_err(){return false}}true}
/// Reusable native compose screen. Configured sender/identity must be reviewed by the app.
pub fn controller(input:Value,m:&email::Mailbox,identity:&str,initial:Value)->Value{controller_with_options(input,m,identity,initial,&Options::default())}
pub fn controller_with_options(input:Value,m:&email::Mailbox,identity:&str,initial:Value,options:&Options)->Value{let mut s=input["state"].clone();if !s.is_object()||s["slot"].as_str().is_some_and(|v|v!=options.slot){s=json!({"binding":binding(m),"draft":initial,"phase":"loading","revision":0,"status":"Loading draft…"});}s["slot"]=json!(options.slot);s["identity"]=json!(identity);let e=&input["event"];let a=e["action"].as_str().unwrap_or("");let ok=e["reply"]["ok"]==true;let v=&e["reply"]["value"];let mut req=Value::Null;let mut show_review=false;let mut closing=false;let mut other_confirm:Option<(&str,&str,&str)>=None;
 if s["binding"]!=binding(m){s=json!({"binding":binding(m),"draft":{},"phase":"blocked","revision":0,"status":"Mail connection changed. Reopen compose."});}
 let editable=s["phase"]=="edit";
 match a{
 "start"=>req=collections::get("mail_draft",&options.slot,"compose.loaded"),
 "compose.loaded" if ok=>{s["revision"]=v["revision"].clone();if v["data"]["binding"]==binding(m){s["draft"]=v["data"]["draft"].clone();s["phase"]=v["data"]["phase"].clone();if v["data"]["identity"].as_str().is_some_and(|v|v!=identity){s["phase"]=json!("blocked");}for k in["attempt","server_email","move_needed"]{s[k]=v["data"][k].clone();}}else if v["data"].is_null(){s["phase"]=json!("edit");}else{s["phase"]=json!("blocked");}s["status"]=json!(if s["phase"]=="edit"{"Draft ready"}else{"Submission state needs review; automatic retry is disabled"});},
 "compose.loaded"=>{s["phase"]=json!("blocked");s["status"]=json!("Could not load draft");},
 "compose.to" if editable=>{s["draft"]["to"]=json!(e["value"].as_str().unwrap_or("").split(',').map(str::trim).filter(|s|!s.is_empty()).collect::<Vec<_>>());s["dirty"]=json!(true);s["exit_after_save"]=json!(false);},
 "compose.subject"|"compose.text" if editable=>{s["draft"][if a=="compose.subject"{"subject"}else{"text"}]=e["value"].clone();s["dirty"]=json!(true);s["exit_after_save"]=json!(false);},
 "compose.save" if editable=>{s["exit_after_save"]=json!(false);req=store(&s);},
 "compose.review" if editable=>match validate(&s["draft"]){Ok(())=>{s["reviewed"]=s["draft"].clone();s["mode"]=json!("review");},Err(err)=>s["status"]=json!(err)},
 "compose.review.submit" if editable&&s["reviewed"].is_object()&&s["reviewed"]==s["draft"]=>show_review=true,
 "compose.review.back"=>{s["mode"]=json!("edit");s["reviewed"]=Value::Null;},
 "compose.cancel"=>{s["reviewed"]=Value::Null;s["mode"]=json!("edit");},
 "compose.confirm" if editable&&s["reviewed"].is_object()&&s["reviewed"]==s["draft"]=>{match submission(m,identity,&s["draft"],None){Ok(_)=>{s["mode"]=json!("edit");s["phase"]=json!("preparing");s["reviewed"]=Value::Null;req=effect("mail.attempt.new",json!({}),"compose.attempt");},Err(err)=>s["status"]=json!(err)}},
 "compose.attempt" if s["phase"]=="preparing"=>{if ok&&v["id"].as_str().is_some_and(|id|id.len()==32&&id.bytes().all(|b|b.is_ascii_hexdigit())){s["attempt"]=json!(format!("{}@onklav.app",v["id"].as_str().unwrap()));s["phase"]=json!("sending");req=store(&s);}else{s["phase"]=json!("edit");s["status"]=json!("Could not prepare a unique send attempt; nothing submitted");}},
 "compose.saved" if ok=>{s["revision"]=v["revision"].clone();s["recovery_unlock"]=json!(false);if s["phase"]=="sending"{s["phase"]=json!("awaiting");req=submission(m,identity,&s["draft"],s["attempt"].as_str()).unwrap_or(Value::Null);s["status"]=json!("Submitting once…");}else if s["phase"]=="submitted"&&s["move_needed"]==true{if let(Some(sent),Some(id))=(&options.sent_mailbox,s["server_email"].as_str()){req=email_recovery::move_to_sent(m,id,sent,"compose.moved").unwrap_or(Value::Null);}s["move_needed"]=json!(false);}else if s["phase"]=="edit"{s["dirty"]=json!(false);s["status"]=json!("Draft saved");if s["exit_after_save"]==true{closing=true;}}},
 "compose.saved" if s["recovery_unlock"]==true=>{s["phase"]=json!("unknown");s["recovery_unlock"]=json!(false);s["status"]=json!("Recovery save failed; previous attempt remains uncertain and locked");},
 "compose.saved"=>{let attempted=s["phase"]=="unknown"||s["phase"]=="submitted";s["phase"]=json!(if attempted{if s["phase"]=="submitted"{"submitted"}else{"unknown"}}else{"edit"});s["status"]=json!(if attempted{"Outcome save failed; check provider and do not retry automatically"}else{"Save failed or conflicted; no submission started"});},
 "compose.submitted"=>{s["phase"]=json!("unknown");s["status"]=json!("Submission outcome uncertain. Check the provider before any retry.");if ok&&accepted(m,v){s["phase"]=json!("submitted");s["status"]=json!("Provider accepted submission; delivery is not confirmed");if let Ok(raw)=http::parse_json(v){s["server_email"]=raw["methodResponses"].as_array().and_then(|r|r.iter().find(|r|r[2]=="create")).map(|r|r[1]["created"]["draft"]["id"].clone()).unwrap_or(Value::Null);}s["move_needed"]=json!(options.sent_mailbox.is_some());}req=store(&s);},
 "compose.attach" if editable&&options.upload_url.is_some()&&s["draft"]["attachments"].as_array().is_some_and(|a|a.len()<3)=>{s["phase"]=json!("attaching");req=blobs::import(false,"compose.imported");},
 "compose.imported" if s["phase"]=="attaching"=>{if ok{if let Some(url)=&options.upload_url{match email_transfer::upload(m,url,v,"compose.uploaded"){Ok(r)=>{s["upload_file"]=v.clone();req=r;},Err(e)=>{s["phase"]=json!("edit");s["status"]=json!(e)}}}}else{s["phase"]=json!("edit");s["status"]=json!("Selection cancelled; draft retained");}},
 "compose.uploaded" if s["phase"]=="attaching"=>{s["phase"]=json!("edit");if ok{match email_transfer::uploaded(m,&s["upload_file"],v){Ok(file)=>{s["draft"]["attachments"].as_array_mut().unwrap().push(file);s["dirty"]=json!(true);s["status"]=json!("Attachment uploaded. Save draft to retain it.");},Err(e)=>s["status"]=json!(e)}}else{s["status"]=json!("Upload failed/cancelled; local file retained and draft unchanged");}},
 _ if a.starts_with("compose.remove.")&&editable=>{if let Ok(i)=a[15..].parse::<usize>(){if let Some(files)=s["draft"]["attachments"].as_array_mut(){if i<files.len(){files.remove(i);s["dirty"]=json!(true);}}}},
 "compose.reconcile" if !editable=>{if let Some(id)=s["attempt"].as_str(){req=email_recovery::find_message(m,id,"compose.found").unwrap_or(Value::Null);}else{s["status"]=json!("Legacy attempt has no correlation ID; check the provider manually");}},
 "compose.found"=>{if ok{match email_recovery::message(m,s["attempt"].as_str().unwrap_or(""),v){Ok(Some(id))=>{s["server_email"]=json!(id);req=email_recovery::submissions(m,s["server_email"].as_str().unwrap(),"compose.checked").unwrap_or(Value::Null);},Ok(None)=>s["status"]=json!("No exact message found. This is NOT proof it was unsent. Keep locked until reviewed."),Err(e)=>s["status"]=json!(e)}}else{s["status"]=json!("Provider lookup failed; send remains locked");}},
 "compose.checked"=>{if ok{match email_recovery::submitted(m,s["server_email"].as_str().unwrap_or(""),v){Ok(true)=>{s["phase"]=json!("submitted");s["move_needed"]=json!(false);s["status"]=json!("Provider submission record found; delivery not confirmed");req=store(&s);},Ok(false)=>s["status"]=json!("No active submission record found. Absence is not proof of non-delivery; no retry enabled."),Err(e)=>s["status"]=json!(e)}}else{s["status"]=json!("Submission lookup failed; send remains locked");}},
 "compose.retry.review" if !editable&&s["phase"]!="submitted"=>other_confirm=Some(("Start a new send attempt?","Only continue after checking the provider. The previous attempt may already have sent. A new confirmation could deliver a duplicate.","compose.retry.accept")),
 "compose.retry.accept" if !editable&&s["phase"]!="submitted"=>{s["recovery_unlock"]=json!(true);s["phase"]=json!("edit");s["attempt"]=Value::Null;s["dirty"]=json!(true);s["status"]=json!("Unlocked by explicit user decision. Review and save before any new confirmed attempt.");req=store(&s);},
 "compose.save_outcome" if !editable=>req=store(&s),
 "compose.move" if s["phase"]=="submitted"=>{if let(Some(sent),Some(id))=(&options.sent_mailbox,s["server_email"].as_str()){req=email_recovery::move_to_sent(m,id,sent,"compose.moved").unwrap_or(Value::Null);}},
 "compose.moved"=>{s["status"]=json!(if ok&&email_recovery::moved(m,s["server_email"].as_str().unwrap_or(""),v){"Submission accepted and stored email moved to Sent; delivery not confirmed"}else{"Submission remains accepted; Sent-folder move failed. Retry move explicitly."});req=store(&s);},
 "compose.back"=>{if editable&&s["dirty"]==true{other_confirm=Some(("Save before leaving?","Save this draft before returning. Choose Stay to keep editing.","compose.save_exit"));}else{closing=true;}},
 "compose.save_exit" if editable=>{s["exit_after_save"]=json!(true);req=store(&s);},
 "compose.discard" if editable=>other_confirm=Some(("Discard unsaved edits?","The previously saved draft will be kept.","compose.discard.accept")),
 "compose.discard.accept" if editable=>closing=true,
 "compose.delete"=>other_confirm=Some(("Delete this local draft?","This removes only the saved local copy. It does not cancel or delete any server submission.","compose.delete.accept")),
 "compose.delete.accept"=>{req=collections::transact("mail_draft",s["revision"].as_u64().unwrap_or(0),1,None,vec![collections::delete(&options.slot)],"compose.deleted");},
 "compose.deleted" if ok=>closing=true,
 _ if a.starts_with("compose.")&&e["reply"]["ok"]==false=>s["status"]=json!("Operation failed; saved draft retained. No automatic submission retry."),_=>{}
 }
 if s["mode"]=="review"&&s["phase"]=="edit"{let mut nodes=vec![heading("compose.review.title","Review email"),label("compose.review.from",&format!("From: {}",s["draft"]["from"].as_str().unwrap_or("")))];for(i,to)in s["draft"]["to"].as_array().into_iter().flatten().enumerate(){nodes.push(label(&format!("compose.review.to.{i}"),&format!("To: {}",to.as_str().unwrap_or(""))));}nodes.push(label("compose.review.subject",s["draft"]["subject"].as_str().unwrap_or("")));nodes.push(label("compose.review.text",s["draft"]["text"].as_str().unwrap_or("")));for(i,a)in s["draft"]["attachments"].as_array().into_iter().flatten().enumerate(){nodes.push(label(&format!("compose.review.attachment.{i}"),a["name"].as_str().unwrap_or("Attachment")));}nodes.push(button("compose.review.submit","Send reviewed message"));let mut screen=Screen::new("Review email",s.clone()).body(nodes).scrollable().back("compose.review.back");if show_review{screen=screen.confirm_labeled("Send reviewed email?",&format!("Send this reviewed message to {} recipient(s) with {} attachment(s)? Submission does not confirm delivery.",s["draft"]["to"].as_array().map_or(0,Vec::len),s["draft"]["attachments"].as_array().map_or(0,Vec::len)),"compose.confirm","compose.cancel","Send");}return screen.finish()}
 let enabled=s["phase"]=="edit";let mut screen=Screen::new("Compose email",s.clone()).body(vec![label("compose.from",&format!("From: {}",s["draft"]["from"].as_str().unwrap_or(""))),field("compose.to","Recipients (comma separated)",&recipients(&s["draft"])).enabled(enabled),field("compose.subject","Subject",s["draft"]["subject"].as_str().unwrap_or("")).enabled(enabled),editor("compose.text","Plain-text message",s["draft"]["text"].as_str().unwrap_or("")).enabled(enabled),label("compose.status",s["status"].as_str().unwrap_or("")),button("compose.save","Save draft").enabled(enabled),button("compose.review","Review send").enabled(enabled)]).effect(req);
 screen=screen.back("compose.back");let body=screen.finish();let mut frame=body;let nodes=frame["body"].as_array_mut().unwrap();for n in nodes.iter_mut(){if n["id"]=="compose.to"{n["limit"]=json!(2048)}if n["id"]=="compose.subject"{n["limit"]=json!(240)}}for (i,a) in s["draft"]["attachments"].as_array().into_iter().flatten().enumerate(){nodes.push(label(&format!("compose.attachment.{i}"),a["name"].as_str().unwrap_or("Attachment")));nodes.push(button(&format!("compose.remove.{i}"),"Remove attachment").enabled(enabled));}if options.upload_url.is_some(){nodes.push(button("compose.attach","Choose attachment file").enabled(enabled));}nodes.push(button("compose.discard","Discard unsaved edits and leave").enabled(enabled));nodes.push(button("compose.delete","Delete local draft"));if !enabled{nodes.push(button("compose.save_outcome","Save current outcome without resending"));}if !enabled{nodes.push(button("compose.reconcile","Check provider submission"));if s["phase"]!="submitted"{nodes.push(button("compose.retry.review","Review unlocking as a new attempt"));}else if options.sent_mailbox.is_some(){nodes.push(button("compose.move","Move stored email to Sent"));}}
 if let Some((title,text,accept))=other_confirm{frame["confirm"]=json!({"title":title,"text":text,"accept":accept,"cancel":"compose.cancel"});}if closing{frame["close_requested"]=json!(true);}if show_review{frame["confirm"]=json!({"title":"Send email?","text":review(&s["draft"]),"accept":"compose.confirm","cancel":"compose.cancel","accept_text":"Send"});}return frame;

}
#[cfg(test)]mod tests{use super::*;fn m()->email::Mailbox{email::Mailbox::new("https://mail.example.org/jmap","a","drafts","opaque").unwrap()}fn d()->Value{json!({"from":"sender@example.org","to":["to@example.org"],"subject":"Demo","text":"Body","attachments":[]})}fn run(s:Value,a:&str,reply:Value)->Value{controller(json!({"state":s,"event":{"action":a,"reply":reply}}),&m(),"identity",d())}fn ready()->Value{let f=run(Value::Null,"start",Value::Null);run(f["state"].clone(),"compose.loaded",json!({"ok":true,"value":{"revision":0,"data":null}}))["state"].clone()}
#[test]fn email_compose_requires_review_and_durable_lock_before_network(){let s=ready();assert!(run(s.clone(),"compose.confirm",Value::Null)["effect"].is_null());let reviewed=run(s,"compose.review",Value::Null);let reviewed=run(reviewed["state"].clone(),"compose.review.submit",Value::Null);assert_eq!(reviewed["confirm"]["accept"],"compose.confirm");let locked=run(reviewed["state"].clone(),"compose.confirm",Value::Null);assert_eq!(locked["effect"]["service"],"mail.attempt.new");let locked=run(locked["state"].clone(),"compose.attempt",json!({"ok":true,"value":{"id":"a".repeat(32)}}));assert_eq!(locked["effect"]["service"],"collections.transact");assert_eq!(locked["state"]["phase"],"sending");let failed=run(locked["state"].clone(),"compose.saved",json!({"ok":false}));assert_ne!(failed["effect"]["service"],"http.request");let sent=run(locked["state"].clone(),"compose.saved",json!({"ok":true,"value":{"revision":1}}));assert_eq!(sent["effect"]["service"],"http.request");assert!(run(sent["state"].clone(),"compose.confirm",Value::Null)["effect"].is_null());}
#[test]fn email_compose_unknown_outcome_and_reopen_never_retry(){let mut s=ready();s["phase"]=json!("awaiting");let f=run(s,"compose.submitted",json!({"ok":false}));assert_eq!(f["state"]["phase"],"unknown");assert_eq!(f["effect"]["service"],"collections.transact");let reopened=run(ready(),"compose.loaded",json!({"ok":true,"value":{"revision":2,"data":{"binding":binding(&m()),"draft":d(),"phase":"sending"}}}));assert!(run(reopened["state"].clone(),"compose.review",Value::Null)["effect"].is_null());}
#[test]fn email_compose_rejects_header_injection_and_changed_review(){let mut bad=d();bad["subject"]=json!("hello\r\nBcc: hidden@example.org");assert!(validate(&bad).is_err());let r=run(ready(),"compose.review",Value::Null);let mut changed=r["state"].clone();changed["draft"]["text"]=json!("Changed");assert!(run(changed,"compose.confirm",Value::Null)["effect"].is_null());}
}

#[cfg(test)]mod receipt_tests{use super::*;#[test]fn qualification_mail_ack_rejects_malformed_duplicate_or_wrong_account(){let m=email::Mailbox::new("https://mail.example.org/jmap","a","drafts","opaque").unwrap();let good=json!({"methodResponses":[["Email/set",{"accountId":"a","created":{"draft":{"id":"d1"}}},"create"],["EmailSubmission/set",{"accountId":"a","created":{"send":{"id":"s1"}}},"submit"]]});let response=|r:&Value|json!({"status":200,"text":r.to_string()});assert!(accepted(&m,&response(&good)));let mut empty=good.clone();empty["methodResponses"][1][1]["created"]["send"]["id"]=json!("");assert!(!accepted(&m,&response(&empty)));let mut duplicate=good.clone();duplicate["methodResponses"][0]=good["methodResponses"][1].clone();assert!(!accepted(&m,&response(&duplicate)));let mut wrong=good.clone();wrong["methodResponses"][0][1]["accountId"]=json!("other");assert!(!accepted(&m,&response(&wrong)));let mut conflict=good;conflict["methodResponses"][1][1]["notCreated"]=json!({"send":{"type":"forbidden"}});assert!(!accepted(&m,&response(&conflict)));}}
#[cfg(test)]mod wrap_tests{use super::*;fn m()->email::Mailbox{email::Mailbox::new("https://mail.example.org/jmap","a","drafts","aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa").unwrap()}fn d()->Value{json!({"from":"sender@example.org","to":["to@example.org"],"subject":"Demo","text":"Body","attachments":[]})}fn options()->Options{Options{slot:"draft_test".into(),upload_url:Some("https://mail.example.org/upload/{accountId}".into()),sent_mailbox:Some("sent".into())}}fn run(state:Value,action:&str,reply:Value)->Value{controller_with_options(json!({"state":state,"event":{"action":action,"reply":reply}}),&m(),"identity",d(),&options())}fn ready()->Value{let f=run(Value::Null,"start",Value::Null);run(f["state"].clone(),"compose.loaded",json!({"ok":true,"value":{"revision":0,"data":null}}))["state"].clone()}
#[test]fn wrap_upload_is_selected_file_then_correlated_server_blob(){let f=run(ready(),"compose.attach",Value::Null);assert_eq!(f["effect"]["service"],"blobs.import");let file=json!({"id":"a".repeat(32),"name":"demo.bin","mime":"application/octet-stream","size":3});let f=run(f["state"].clone(),"compose.imported",json!({"ok":true,"value":file}));assert_eq!(f["effect"]["args"]["upload"],"a".repeat(32));let response=json!({"status":201,"text":json!({"accountId":"a","blobId":"server","type":"application/octet-stream","size":3}).to_string()});let f=run(f["state"].clone(),"compose.uploaded",json!({"ok":true,"value":response}));assert_eq!(f["state"]["draft"]["attachments"][0]["blobId"],"server");assert_eq!(f["state"]["phase"],"edit");}
#[test]fn wrap_unknown_recovery_never_unlocks_on_absence_and_conflict_relocks(){let mut state=ready();state["phase"]=json!("unknown");state["attempt"]=json!("attempt@onklav.app");let f=run(state,"compose.reconcile",Value::Null);assert_eq!(f["effect"]["service"],"http.request");assert!(!f["effect"]["args"]["body"].as_str().unwrap().contains("EmailSubmission/set"));let absent=json!({"status":200,"text":json!({"methodResponses":[["Email/query",{"accountId":"a","ids":[]},"q"],["Email/get",{"accountId":"a","notFound":[],"list":[]},"g"]]}).to_string()});let f=run(f["state"].clone(),"compose.found",json!({"ok":true,"value":absent}));assert_eq!(f["state"]["phase"],"unknown");assert!(f["effect"].is_null());let review=run(f["state"].clone(),"compose.retry.review",Value::Null);assert_eq!(review["confirm"]["accept"],"compose.retry.accept");let unlocked=run(review["state"].clone(),"compose.retry.accept",Value::Null);assert_eq!(unlocked["effect"]["service"],"collections.transact");let failed=run(unlocked["state"].clone(),"compose.saved",json!({"ok":false}));assert_eq!(failed["state"]["phase"],"unknown");assert!(failed["effect"].is_null());}
#[test]fn wrap_dirty_back_saves_before_exit_and_sent_move_is_not_resend(){let mut state=ready();state["dirty"]=json!(true);let back=run(state,"compose.back",Value::Null);assert_eq!(back["confirm"]["accept"],"compose.save_exit");let saving=run(back["state"].clone(),"compose.save_exit",Value::Null);assert_eq!(saving["effect"]["service"],"collections.transact");let saved=run(saving["state"].clone(),"compose.saved",json!({"ok":true,"value":{"revision":1}}));assert_eq!(saved["close_requested"],true);let mut state=ready();state["phase"]=json!("submitted");state["server_email"]=json!("email-id");let moved=run(state,"compose.move",Value::Null);let body=moved["effect"]["args"]["body"].as_str().unwrap();assert!(body.contains("Email/set"));assert!(!body.contains("EmailSubmission/set"));}
}
